/*
 * Función de salida de un carácter.
 *
 * El atributo weak significa que puede existir sin una implementación
 * fuerte dentro de este archivo. Otro módulo puede proporcionar una función
 * con el mismo nombre para redirigir los caracteres hacia:
 *
 *   - USART1.
 *   - SWO.
 *   - USB CDC.
 *   - Otra interfaz.
 *
 * Ejemplo típico:
 *
 *   int __io_putchar(int ch)
 *   {
 *       HAL_UART_Transmit(&huart1, (uint8_t *)&ch, 1U, 100U);
 *       return ch;
 *   }
 */
extern int __io_putchar(int ch) __attribute__((weak));


/*
 * Función de entrada de un carácter.
 *
 * También es weak para permitir una implementación personalizada,
 * normalmente mediante UART.
 */
extern int __io_getchar(void) __attribute__((weak));


/*
 * Entorno mínimo del proceso.
 *
 * En sistemas POSIX, environ contiene variables de entorno como:
 *
 *   PATH
 *   HOME
 *   LANG
 *
 * En el STM32 no existen variables de entorno reales. Se crea un arreglo
 * con un único puntero nulo para satisfacer a la biblioteca estándar.
 */
char *__env[1] = { 0 };

/*
 * Puntero global esperado por ciertas funciones de la biblioteca C.
 *
 * Apunta al entorno vacío definido anteriormente.
 */
char **environ = __env;


