/**
 * @brief Devuelve un identificador de proceso ficticio.
 *
 * Un STM32 bare-metal no posee procesos POSIX. Se devuelve siempre 1 para
 * satisfacer las funciones de Newlib que esperan un PID válido.
 *
 * @return Identificador ficticio del único programa en ejecución.
 */
int _getpid(void)
{
  return 1;
}


/**
 * @brief Simula el envío de una señal a un proceso.
 *
 * El STM32 no implementa procesos ni señales POSIX, por lo que la operación
 * siempre falla.
 *
 * @param pid Identificador del proceso solicitado.
 * @param sig Señal solicitada.
 *
 * @return -1 para indicar error.
 */
int _kill(int pid, int sig)
{
  /*
   * Evitar advertencias del compilador por parámetros no utilizados.
   */
  (void)pid;
  (void)sig;

  /*
   * EINVAL indica que el argumento o la operación no son válidos.
   */
  errno = EINVAL;

  return -1;
}


/**
 * @brief Finaliza la aplicación.
 *
 * En un sistema operativo, _exit() devolvería el control al sistema.
 * En un microcontrolador no existe un sistema al cual regresar.
 *
 * La implementación:
 *
 *   1. Llama a _kill() para registrar un error.
 *   2. Entra permanentemente en un bucle infinito.
 *
 * @param status Código de salida solicitado por la aplicación.
 */
void _exit(int status)
{
  /*
   * Utiliza status como identificador ficticio y -1 como señal.
   *
   * _kill() siempre asignará errno = EINVAL y devolverá -1.
   */
  _kill(status, -1);

  /*
   * Impedir que la ejecución continúe después de exit().
   */
  while (1)
  {
  }
}


/**
 * @brief Implementación mínima de lectura para Newlib.
 *
 * Puede ser utilizada internamente por:
 *
 *   - scanf().
 *   - getchar().
 *   - fread() sobre stdin.
 *
 * Se intenta leer exactamente len caracteres mediante __io_getchar().
 *
 * El atributo weak permite reemplazar toda la función _read() desde otro
 * archivo por una implementación más apropiada.
 *
 * @param file Descriptor de archivo.
 *             Normalmente 0 representa stdin.
 * @param ptr  Buffer donde se guardarán los caracteres recibidos.
 * @param len  Cantidad de caracteres solicitados.
 *
 * @return Cantidad de caracteres leídos.
 */
__attribute__((weak)) int _read(int file, char *ptr, int len)
{
  /*
   * Esta implementación ignora el descriptor.
   *
   * Tratará igual stdin y cualquier otro valor.
   */
  (void)file;

  /*
   * Índice del carácter que se está leyendo.
   */
  int DataIdx;

  /*
   * Leer exactamente len caracteres.
   *
   * ptr++ guarda el carácter en la posición actual y después avanza
   * el puntero a la siguiente posición.
   */
  for (DataIdx = 0; DataIdx < len; DataIdx++)
  {
    *ptr++ = __io_getchar();
  }

  /*
   * Se informa que se leyeron todos los caracteres solicitados.
   */
  return len;
}


/**
 * @brief Implementación mínima de escritura para Newlib.
 *
 * Puede ser utilizada internamente por:
 *
 *   - printf().
 *   - puts().
 *   - putchar().
 *   - fwrite() sobre stdout o stderr.
 *
 * Cada carácter se entrega individualmente a __io_putchar().
 *
 * El atributo weak permite reemplazar toda la función desde otro módulo.
 *
 * @param file Descriptor de archivo.
 *             Normalmente 1 representa stdout y 2 representa stderr.
 * @param ptr  Buffer que contiene los datos que se transmitirán.
 * @param len  Cantidad de caracteres que se transmitirán.
 *
 * @return Cantidad de caracteres informados como escritos.
 */
__attribute__((weak)) int _write(int file, char *ptr, int len)
{
  /*
   * La implementación no distingue entre stdout, stderr u otros
   * descriptores.
   */
  (void)file;

  /*
   * Índice del carácter que se está transmitiendo.
   */
  int DataIdx;

  /*
   * Transmitir cada carácter individualmente.
   */
  for (DataIdx = 0; DataIdx < len; DataIdx++)
  {
    __io_putchar(*ptr++);
  }

  /*
   * Se informa que se escribieron todos los caracteres, aunque
   * __io_putchar() no haya sido comprobado.
   */
  return len;
}


